<?php
declare(strict_types=1);require_once __DIR__.'/includes/ui.php';pv_require_login();$db=pv_db();$uid=(int)$_SESSION['myid'];$notice='';$error='';
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
    try{
        pv_require_csrf();$action=(string)($_POST['action']??'profile');
        if($action==='profile'){
            $email=trim((string)($_POST['email']??''));$bio=trim((string)($_POST['bio']??''));if(!filter_var($email,FILTER_VALIDATE_EMAIL))throw new RuntimeException('Enter a valid email address.');if(strlen($bio)>500)throw new RuntimeException('Bio must be 500 characters or fewer.');$stmt=$db->prepare('UPDATE members SET email=?,bio=? WHERE id=?');$stmt->bind_param('ssi',$email,$bio,$uid);if(!$stmt->execute()){if($stmt->errno===1062)throw new RuntimeException('That email is already registered.');throw new RuntimeException($stmt->error);}$stmt->close();$notice='Tamer profile saved.';dn_world_event('game','profile.update','Tamer profile updated');
        }elseif($action==='password'){
            $current=(string)($_POST['current_password']??'');$new=(string)($_POST['new_password']??'');$confirm=(string)($_POST['confirm_password']??'');$stmt=$db->prepare('SELECT password,session_version FROM members WHERE id=?');$stmt->bind_param('i',$uid);$stmt->execute();$row=$stmt->get_result()->fetch_assoc();$stmt->close();if(!$row||!pv_password_matches($current,(string)$row['password']))throw new RuntimeException('Current password is incorrect.');if(strlen($new)<8)throw new RuntimeException('New password must contain at least 8 characters.');if($new!==$confirm)throw new RuntimeException('New password confirmation does not match.');$hash=pv_password_hash($new);$version=(int)$row['session_version'];$stmt=$db->prepare('UPDATE members SET password=?,session_version=session_version+1 WHERE id=? AND password=? AND session_version=?');$stmt->bind_param('sisi',$hash,$uid,$row['password'],$version);$stmt->execute();$changed=$stmt->affected_rows;$stmt->close();if($changed!==1)throw new RuntimeException('Account security changed. Sign in again and retry.');$_SESSION['session_version']=$version+1;session_regenerate_id(true);$notice='Password updated securely. Other sessions have been signed out.';dn_world_event('auth','password.changed','Tamer changed their password and revoked other sessions');
        }
    }catch(Throwable $e){$error=$e->getMessage();}
}
$stmt=$db->prepare('SELECT m.*,COALESCE(o.tamer,m.created_avatar,1) tamer FROM members m LEFT JOIN members_options o ON o.id=m.id WHERE m.id=? LIMIT 1');$stmt->bind_param('i',$uid);$stmt->execute();$member=$stmt->get_result()->fetch_assoc();$stmt->close();$owned=count(dn_collection_rows($db,$uid));$party=dn_party_rows($db,$uid);$scan=0;$seen=0;$stmt=$db->prepare('SELECT COUNT(*) seen,COALESCE(SUM(scan_percent),0) scan FROM digimon_scan WHERE owner_id=?');$stmt->bind_param('i',$uid);$stmt->execute();$r=$stmt->get_result()->fetch_assoc();$stmt->close();$seen=(int)$r['seen'];$scan=(int)$r['scan'];$unread=dn_unread_counts($db,$uid);pv_page_start('Tamer Profile','your_account.php',true);
?>
<div class="pv-game-layout"><?php pv_game_side_menu('your_account.php');?><main class="pv-main-column"><section class="pv-page"><div class="pv-page-head"><?php nxt_page_sprites();?><div><span class="pv-eyebrow">NXT TAMER RECORD</span><h1><?=pv_h((string)$member['username'])?></h1><p class="pv-subtle">Persistent account, public tamer profile and network progression.</p></div><img class="dn-map-avatar" style="width:82px;height:82px" src="<?=pv_h(nxt_skin_url((int)$member['tamer']))?>" alt="Tamer avatar"></div><?php if($notice):?><div class="pv-flash success"><?=pv_h($notice)?></div><?php endif;?><?php if($error):?><div class="pv-flash error"><?=pv_h($error)?></div><?php endif;?><div class="dn-stat-strip"><div><span>Owned Digimon</span><strong><?=$owned?></strong></div><div><span>Party Links</span><strong><?=count($party)?>/6</strong></div><div><span>Species Seen</span><strong><?=$seen?></strong></div><div><span>Bits</span><strong><?=number_format((int)$member['money'])?></strong></div></div><section class="pv-grid cols-3" style="margin-top:14px"><article class="pv-card" style="padding:18px"><small>BATTLES</small><strong style="display:block;font-size:28px"><?=(int)$member['battle']?></strong><p><?=(int)$member['wins']?> wins · <?=(int)$member['losses']?> losses</p></article><article class="pv-card" style="padding:18px"><small>TOTAL EXP</small><strong style="display:block;font-size:28px"><?=number_format((int)$member['totalexp'])?></strong><p><?=number_format($scan)?>% cumulative scan data</p></article><article class="pv-card" style="padding:18px"><small>UNREAD SIGNALS</small><strong style="display:block;font-size:28px"><?=($unread['messages']+$unread['notifications'])?></strong><p><?=$unread['messages']?> messages · <?=$unread['notifications']?> notifications</p></article></section><section class="pv-grid cols-2" style="margin-top:14px"><form class="pv-card" style="padding:20px" method="post"><?=pv_csrf_field()?><input type="hidden" name="action" value="profile"><h2>Profile</h2><div class="pv-field"><label>Email</label><input type="email" name="email" maxlength="160" value="<?=pv_h((string)$member['email'])?>" required></div><div class="pv-field"><label>Public bio</label><textarea name="bio" rows="5" maxlength="500"><?=pv_h((string)$member['bio'])?></textarea></div><button class="pv-button">Save Profile</button><div class="pv-actions"><a class="pv-button pv-button-secondary" href="<?=pv_h(pv_url('profile.php?id='.$uid))?>">Public View</a><a class="pv-button pv-button-secondary" href="<?=pv_h(pv_url('options.php'))?>">Network Options</a><?php if(in_array((string)$member['role'],['admin','moderator'],true)):?><a class="pv-button pv-button-secondary" href="<?=pv_h(pv_url('admin.php'))?>">Administration</a><?php endif;?></div></form><form class="pv-card" style="padding:20px" method="post"><?=pv_csrf_field()?><input type="hidden" name="action" value="password"><h2>Security</h2><div class="pv-field"><label>Current password</label><input type="password" name="current_password" required></div><div class="pv-field"><label>New password</label><input type="password" name="new_password" minlength="8" required></div><div class="pv-field"><label>Confirm new password</label><input type="password" name="confirm_password" minlength="8" required></div><button class="pv-button">Update Password</button></form></section></section></main></div><?php pv_page_end(); ?>
